def _view_sections():
    """Return the independently renderable top-level admin page sections."""

    starts = {
        view: HTML.index(f'<section id="{element}"')
        for view, element in (
            ("dashboard", "dashboardView"),
            ("models", "modelsView"),
            ("usage", "usageView"),
            ("security", "securityView"),
            ("keys", "keysView"),
            ("settings", "settingsView"),
        )
    }
    ordered = sorted(starts.items(), key=lambda item: item[1])
    end = HTML.index("</main></div>", ordered[-1][1])
    return {
        view: HTML[offset : ordered[index + 1][1] if index + 1 < len(ordered) else end]
        for index, (view, offset) in enumerate(ordered)
    }, ordered[0][1], end


_PAGE_SECTIONS, _MAIN_START, _MAIN_END = _view_sections()
_PAGE_PREFIX = HTML[:_MAIN_START]
_PAGE_SUFFIX = HTML[_MAIN_END:]


